oracle_code:
def oracle(input):
    n = input[0]
    a = input[1]
    a = sorted(a)
    if n == 0:
        return 0
    best = None
    c = 1
    while True:
        cur = 1
        cost = 0
        ok = True
        for i in range(n):
            cost += abs(a[i] - cur)
            if best is not None and cost >= best:
                break
            if i != n - 1:
                if cur > 10**18 // c:
                    ok = False
                    break
                cur *= c
        if best is None or cost < best:
            best = cost
        if c == 1:
            c = 2
            continue
        cur = 1
        overflow = False
        for i in range(1, n):
            if cur > 10**18 // c:
                overflow = True
                break
            cur *= c
            if cur > 10**18:
                overflow = True
                break
        if overflow or cur > 2 * 10**9:
            break
        c += 1
    return best

init_state_code:
def init_state(input):
    n = input[0]
    a = input[1]
    return list(a)

apply_op_code:
def apply_op(state, i):
    j = i // 2
    if i % 2 == 0:
        state[j] -= 1
    else:
        state[j] += 1

goal_code:
def goal_reached(state, input):
    n = input[0]
    if len(state) != n:
        return False
    b = sorted(state)
    if b[0] != 1:
        return False
    c = b[1]
    cur = 1
    for i in range(n):
        if b[i] != cur:
            return False
        cur *= c
    return True
